#include <stdarg.h>

int sum(int count, ...) {
    va_list ap;
    va_start(ap, count);
    int total = 0;
    for (int i = 0; i < count; i++) total += va_arg(ap, int);
    va_end(ap);
    return total;
}

int process(size_t n) {
    int rc = -1;
    char *buf = malloc(n);
    if (!buf) goto out;
    memset(buf, 'x', n);
    rc = buf[0];
    free(buf);
out:
    return rc;
}

